SELECT 'profit_uu_by_year' test,jsonb_agg(x) data FROM (SELECT year,count(*) company_years,count(profit_net) with_profit FROM reference.company_financials WHERE category='UU' GROUP BY 1 ORDER BY 1) x
UNION ALL SELECT 'profit_uu_active_suppliers',jsonb_agg(x) FROM (SELECT cf.year,count(*) suppliers,count(*) FILTER(WHERE cf.profit_net IS NULL) missing_profit FROM reference.company_financials cf JOIN core.entities e ON e.cui_canonical=cf.cui JOIN marts.entity_profile ep ON ep.entity_id=e.id AND ep.role='supplier' WHERE cf.category='UU' GROUP BY 1 ORDER BY 1) x
UNION ALL SELECT 'profit_examples',jsonb_agg(x) FROM (SELECT cui,year,category,profit_net::text,net_turnover::text FROM reference.company_financials WHERE cui IN ('30976819','16617020') AND year=2025) x
UNION ALL SELECT 'reps_active_suppliers',to_jsonb(x) FROM (SELECT count(*) rows,count(*) FILTER(WHERE birth_date IS NULL) missing_birth_date,count(distinct r.cui) firms,count(distinct r.cui) FILTER(WHERE birth_date IS NULL) firms_with_missing_birth_date FROM reference.company_reps r JOIN core.entities e ON e.cui_canonical=r.cui JOIN marts.entity_profile ep ON ep.entity_id=e.id AND ep.role='supplier' WHERE r.calitate ILIKE '%administrator%') x
